+    #[test]
+    fn plain_http_is_only_allowed_for_loopback() {
+        assert!(is_secure_endpoint("https://eu.memory.redis.io"));
+        assert!(is_secure_endpoint("https://<region>.langcache.redis.io"));
+        assert!(is_secure_endpoint("http://localhost:8080"));
